import { LayoutGrid, Server, Database, Wrench } from "lucide-react";
import { cn } from "@/lib/utils";

const CATEGORY_ORDER = ["Frontend", "Backend", "Database", "Tools"];

const CATEGORY_CONFIG = {
  Frontend: { icon: LayoutGrid, accent: "#FF5005", tint: "rgba(255, 80, 5, 0.12)" },
  Backend: { icon: Server, accent: "#F7C948", tint: "rgba(247, 201, 72, 0.12)" },
  Database: { icon: Database, accent: "#38BDF8", tint: "rgba(56, 189, 248, 0.12)" },
  Tools: { icon: Wrench, accent: "#A78BFA", tint: "rgba(167, 139, 250, 0.12)" },
};

// Display grouping for the existing skills data (data array stays untouched).
const ASSIGN = {
  1: "Frontend", 2: "Frontend", 3: "Frontend", 4: "Frontend", 5: "Frontend",
  6: "Frontend", 7: "Frontend", 12: "Frontend", 15: "Frontend",
  8: "Backend", 9: "Backend", 17: "Backend", 18: "Backend", 19: "Backend",
  27: "Backend", 28: "Backend", 29: "Backend",
  10: "Database", 11: "Database", 23: "Database", 24: "Database", 25: "Database", 26: "Database",
  13: "Tools", 14: "Tools", 16: "Tools", 20: "Tools", 21: "Tools", 22: "Tools",
  30: "Tools", 31: "Tools", 32: "Tools",
};

const SkillPanel = ({ category, skills, index }) => {
  const { icon: Icon, accent, tint } = CATEGORY_CONFIG[category];
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      { threshold: 0.15 }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <div
      ref={ref}
      style={{ transitionDelay: `${index * 100}ms` }}
      className={cn(
        "rounded-2xl border border-white/10 bg-white/5 backdrop-blur-lg p-6 shadow-md",
        "transition-all duration-700 ease-out will-change-transform",
        visible
          ? "opacity-100 translate-y-0"
          : "opacity-0 translate-y-8 motion-reduce:translate-y-0 motion-reduce:opacity-100 motion-reduce:transition-none"
      )}
    >
      <span
        aria-hidden
        className="block mb-5 h-1 w-12 rounded-full"
        style={{ background: accent }}
      />

      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center gap-3">
          <span
            aria-hidden
            className="flex h-11 w-11 items-center justify-center rounded-xl"
            style={{ background: tint, color: accent }}
          >
            <Icon size={22} />
          </span>
          <h3 className="text-xl font-semibold text-[#EFECE3]">{category}</h3>
        </div>
        <span
          className="rounded-full border px-2.5 py-0.5 text-xs font-semibold"
          style={{ color: accent, borderColor: accent }}
        >
          {skills.length}
        </span>
      </div>

      <ul className="flex flex-wrap gap-2.5">
        {skills.map((skill) => (
          <li
            key={skill.id}
            className="flex items-center gap-2.5 rounded-lg border border-white/10 bg-white/5 px-3 py-2 text-sm text-neutral-200 transition hover:-translate-y-0.5 hover:border-white/25"
          >
            <span
              aria-hidden
              className="flex h-6 w-6 items-center justify-center [&_svg]:h-6 [&_svg]:w-6"
              dangerouslySetInnerHTML={{ __html: skill.svg }}
            />
            <span className="font-medium">{skill.name}</span>
          </li>
        ))}
      </ul>
    </div>
  );
};

